def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        if not row:
            continue
        first = row[0]
        i = 1
        while i < len(row) and row[i] == first:
            i += 1
        if i < len(row):
            row[i:] = [1] * (len(row) - i)
    return out
